export const getBasicHexagonGeometry = () => {
  const hexGeometry: XyPosition[] = [];
  for (let i = 0; i < 6; i++) {
    hexGeometry.push(basicHexagonVertexes[i]);
    hexGeometry.push(basicHexagonLinesBisect[i]);
  }

  hexGeometry.push(basicHexagonVertexes[0]);
  hexGeometry.push(basicHexagonLinesBisect[0]);

  return hexGeometry;
};
